public boolean validateWrite()
{
    boolean ret = next validateWrite();

    TAMRebateDeal deal = TAMRebateDeal::find(this.RebateDeal);
    if (TAMRebateDealGUPExtensionHelper::shouldShowGUPUI(null, deal.ModuleInventCustVend, true))
    {
        if (deal.Recipient && deal.RebateReconciliation == TAMRebateReconciliation::Line)
        {
            if (!this.RebatePostingId)
            {
                ret = checkFailed(strFmt("@SYS26332", fieldId2PName(tableNum(TAMRebateTable), fieldNum(TAMRebateTable, RebatePostingId))));
            }
            else
            {
                TAMRebatePosting rebatePosting = TAMRebatePosting::find(this.RebatePostingId, this.ModuleInventCustVend);
                if (rebatePosting.RebatePostingType != TAMRebatePostingAccountType::CustVend)
                {
                    ret = checkFailed("@GlobalUnifiedPricing:RebatePostingTypeMustBeCustVend");
                }
            }
        }
    }

    return ret;
}

[SysClientCacheDataMethodAttribute(true)]
public display GUPPriceAttributeGroupPriority displayCombinationPriceAttributeGroupPriority()
{
    GUPPriceComponentCodePriceAttributeGroupCombination priceAttributeGroupCombination;

    select firstonly Priority from priceAttributeGroupCombination
        where priceAttributeGroupCombination.RecId == this.PriceComponentCombination;

    return priceAttributeGroupCombination.Priority;
}

public GUPPricingAttributeGroupCombinationName getPriceComponentCodeName()
{
    GUPPriceComponentCodePriceAttributeGroupCombination combination;
    select firstonly PriceComponentCodeName from combination where combination.RecId == this.PriceComponentCombination;

    return combination.PriceComponentCodeName;
}

public GUPPriceAttributeGroupPriority getPriority()
{
    GUPPriceComponentCodePriceAttributeGroupCombination combination;
    select firstonly Priority from combination where combination.RecId == this.PriceComponentCombination;

    return combination.Priority;
}
